// Test fixture: the TypeScript hello agent. Attended, it asks first; the answer arrives as the next prompt.
// The node runs agent.mjs: this file with the SDK inlined, generated by the Agent SDK's examples/vendor.py.

import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { run, type Turn } from "@jaah/agent-sdk";

const asked = new Map<string, string>(); // session id -> the question it is waiting on

async function finish(turn: Turn, task: { title: string }, summary: string, evidence: string): Promise<void> {
  // Upload a report on EVERY path, the decline included: some kinds of task refuse a settle without one.
  const report = join(process.env.JAAH_REPORT_DIR ?? ".", "report.html");
  const esc = (s: string) => s.replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[c]!);
  writeFileSync(report, `<!doctype html><title>Hello</title><p>${esc(task.title)}: ${esc(summary)}</p>`);
  await turn.jaah.call("artifact.upload", { kind: "report", path: report });
  await turn.complete(summary, "no_pr", { no_pr_reason: "no_code_needed", no_pr_evidence: evidence });
}

run({
  info: { name: "ts-hello", version: "2.0.0" },
  async prompt(turn: Turn) {
    const task = (await turn.jaah.call("task.get")) as { id: number; title: string; autonomous: boolean };
    const question = asked.get(turn.sessionId);
    asked.delete(turn.sessionId);
    if (question === undefined) {
      if (!task.autonomous) { // Full Auto: decide yourself, never ask
        const q = `Say hello for task ${task.id}?`;
        await turn.jaah.ask(q, { header: "Confirm", options: [{ label: "Yes" }, { label: "No" }] });
        asked.set(turn.sessionId, q);
        return; // the answer is the next prompt
      }
    } else {
      const answer = turn.text.replace(`Answer to your question '${question}': `, "").trim();
      if (answer !== "Yes") {
        await finish(turn, task, "The operator declined the hello.", "Operator answered other than Yes.");
        return;
      }
    }
    await turn.say("Hello from TS hello!\n");
    await turn.update({
      sessionUpdate: "usage_update", used: 0, size: 0,
      _meta: { "jaah.ai": { usage: { model: "my-model-1", input_tokens: 120, output_tokens: 40 } } },
    });
    await finish(turn, task, "Said hello.", "Hello agent: no code change requested.");
  },
});
